        adj.setdefault(v, [])  # ensure target nodes exist in dict

    # Breadth‑first search returning the number of edges, or None if unreachable
    def bfs(start, goal):
        if start == goal:
            return 0
        visited = {start}
        q = deque([(start, 0)])
        while q:
            node, dist = q.popleft()
            for nxt in adj.get(node, []):
                if nxt == goal:
                    return dist + 1
                if nxt not in visited:
                    visited.add(nxt)
                    q.append((nxt, dist + 1))
        return None

    if source == target:
        # shortest positive‑length cycle returning to source
        best = None
        for nxt in adj.get(source, []):
            d = bfs(nxt, source)   # distance from neighbour back to source
            if d is not None:
                cand = 1 + d
                if best is None or cand < best:
                    best = cand
        return best if best is not None else -1
    else:
        d = bfs(source, target)
        return d if d is not None else -1
