    def bfs(start, goal, allow_zero_cycle=False):
        q = deque()
        q.append((start, 0))
        visited = set()
        # For the special case where start==goal we want a cycle >0,
        # so we do NOT mark the start as visited initially.
        if not allow_zero_cycle:
            visited.add(start)

        while q:
            node, dist = q.popleft()
            # If we are looking for a cycle and we have returned to start
            if allow_zero_cycle and node == start and dist > 0:
                return dist
            # Normal target check
            if node == goal and not (allow_zero_cycle and dist == 0):
                return dist
            for nb in adj.get(node, []):
                if nb not in visited:
                    visited.add(nb)
                    q.append((nb, dist + 1))
        return -1

    if source == target:
        # Need a positive‑length round trip (shortest directed cycle)
        return bfs(source, source, allow_zero_cycle=True)
    else:
        return bfs(source, target)
